/** SpaceKind is what a space holds. */
export type SpaceKind = 'workspace' | 'project' | 'team' | 'end_user' | 'agent' | 'shared' | (string & {})

/** SpaceRole is a share relation on a space. */
export type SpaceRole = 'reader' | 'writer' | 'owner' | (string & {})

