/**
 * KnowledgeService is Sylphx Knowledge: one permission-aware knowledge graph
 * that people, apps and agents write while they work and read through search
 * with citations. Episodes are the sources; entities and relations (facts)
 * are what is known, each with provenance and valid and recorded time.
 * Every record lives in one Space, and a caller sees a record only through a
 * space it may read, so a context pack or an answer never cites a source the
 * caller cannot open.
 *
 * Namespace of Sylphx Knowledge on `Sylphx`.
 */
export class KnowledgeApi {
	private readonly client: runtime.Client
	/** The `spaces` collection. */
	readonly spaces: SpacesCollection
	/** The `knowledge_schemas` collection. */
	readonly knowledgeSchemas: KnowledgeSchemasCollection
	/** The `episodes` collection. */
	readonly episodes: EpisodesCollection
	/** The `entities` collection. */
	readonly entities: EntitiesCollection
	/** The `relations` collection. */
	readonly relations: RelationsCollection

	constructor(client: runtime.Client) {
		this.client = client
		this.spaces = new SpacesCollection(client)
		this.knowledgeSchemas = new KnowledgeSchemasCollection(client)
		this.episodes = new EpisodesCollection(client)
		this.entities = new EntitiesCollection(client)
		this.relations = new RelationsCollection(client)
	}

	/**
	 * Records an episode and returns at once (`remember`); extraction reads
	 * it afterwards.
	 *
	 * `POST /v1/{parent=orgs/*\/projects/*\/envs/*\/spaces/*}/episodes` · permission `knowledge:write` · effect `write`
	 *
	 * Errors: `UNAUTHENTICATED`, `PERMISSION_DENIED`, `UNKNOWN_FIELD`, `INVALID_FIELD`, `RESOURCE_ALREADY_EXISTS`, `RATE_LIMITED`, `SPEND_LIMIT_REACHED`, `IDEMPOTENCY_KEY_REUSED`, `IDEMPOTENCY_IN_PROGRESS`.
	 *
	 * Short name of `sx.knowledge.episodes.create`.
	 */
	async remember(request: CreateEpisodeRequest): Promise<Episode> {
		return this.client.call<Episode>({
			method: 'POST',
			path: `/v1/${runtime.pathParam(request.parent, 'orgs/*/projects/*/envs/*/spaces/*', 'parent')}/episodes`,
			query: { episode_id: request.episodeId, validate_only: request.validateOnly, skip_extraction: request.skipExtraction },
			body: request.episode ?? {},
			bodyType: 'sylphx.knowledge.v1.Episode',
			responseType: 'sylphx.knowledge.v1.Episode',
			mutation: true,
		})
	}

	/**
	 * Returns one entity's profile in one call (`entity`): the entity, its
	 * current facts in both directions, the entities they name and the recent
	 * episodes about it, trimmed to what the caller may see. A read with a
	 * request body.
	 *
	 * `POST /v1/{name=orgs/*\/projects/*\/envs/*\/entities/*}:profile` · permission `knowledge:read` · effect `read`
	 *
	 * Errors: `UNAUTHENTICATED`, `PERMISSION_DENIED`, `RESOURCE_NOT_FOUND`, `INVALID_FIELD`.
	 *
	 * Short name of `sx.knowledge.entities.profile`.
	 */
	async entity(request: ProfileEntityRequest): Promise<ProfileEntityResponse> {
		return this.client.call<ProfileEntityResponse>({
			method: 'POST',
			path: `/v1/${runtime.pathParam(request.name, 'orgs/*/projects/*/envs/*/entities/*', 'name')}:profile`,
			body: runtime.omit(request, ['name']),
			bodyType: 'sylphx.knowledge.v1.ProfileEntityRequest',
			responseType: 'sylphx.knowledge.v1.ProfileEntityResponse',
			mutation: true,
		})
	}

	/**
	 * Searches the graph (`recall`): hybrid lexical and semantic search over
	 * episodes and facts, fused by reciprocal rank, then at most two hops of
	 * expansion from the top entities. Returns a context pack with citations,
	 * built only from records the caller may see.
	 *
	 * `POST /v1/{parent=orgs/*\/projects/*\/envs/*}/entities:recall` · permission `knowledge:read` · effect `read`
	 *
	 * Errors: `UNAUTHENTICATED`, `PERMISSION_DENIED`, `INVALID_FIELD`, `RATE_LIMITED`.
	 *
	 * Short name of `sx.knowledge.entities.recall`.
	 */
	async recall(request: RecallEntitiesRequest): Promise<RecallEntitiesResponse> {
		return this.client.call<RecallEntitiesResponse>({
			method: 'POST',
			path: `/v1/${runtime.pathParam(request.parent, 'orgs/*/projects/*/envs/*', 'parent')}/entities:recall`,
			body: runtime.omit(request, ['parent']),
			bodyType: 'sylphx.knowledge.v1.RecallEntitiesRequest',
			responseType: 'sylphx.knowledge.v1.RecallEntitiesResponse',
			mutation: true,
		})
	}

	/**
	 * Answers a question through Sylphx AI (`ask`), from a context pack built
	 * only from records the caller may see, with citations to its episodes.
	 *
	 * `POST /v1/{parent=orgs/*\/projects/*\/envs/*}/entities:ask` · permission `knowledge:read` · effect `read`
	 *
	 * Errors: `UNAUTHENTICATED`, `PERMISSION_DENIED`, `INVALID_FIELD`, `RATE_LIMITED`, `SPEND_LIMIT_REACHED`.
	 *
	 * Short name of `sx.knowledge.entities.ask`.
	 */
	async ask(request: AskEntitiesRequest): Promise<AskEntitiesResponse> {
		return this.client.call<AskEntitiesResponse>({
			method: 'POST',
			path: `/v1/${runtime.pathParam(request.parent, 'orgs/*/projects/*/envs/*', 'parent')}/entities:ask`,
			body: runtime.omit(request, ['parent']),
			bodyType: 'sylphx.knowledge.v1.AskEntitiesRequest',
			responseType: 'sylphx.knowledge.v1.AskEntitiesResponse',
			mutation: true,
		})
	}

	/**
	 * Records a fact in a space (`relate`). A fact that contradicts a current
	 * one with the same subject and a single-valued predicate closes the older
	 * fact; nothing is overwritten.
	 *
	 * `POST /v1/{parent=orgs/*\/projects/*\/envs/*\/spaces/*}/relations` · permission `knowledge:write` · effect `write`
	 *
	 * Errors: `UNAUTHENTICATED`, `PERMISSION_DENIED`, `UNKNOWN_FIELD`, `INVALID_FIELD`, `RESOURCE_ALREADY_EXISTS`, `IDEMPOTENCY_KEY_REUSED`, `IDEMPOTENCY_IN_PROGRESS`.
	 *
	 * Short name of `sx.knowledge.relations.create`.
	 */
	async relate(request: CreateRelationRequest): Promise<Relation> {
		return this.client.call<Relation>({
			method: 'POST',
			path: `/v1/${runtime.pathParam(request.parent, 'orgs/*/projects/*/envs/*/spaces/*', 'parent')}/relations`,
			query: { relation_id: request.relationId, validate_only: request.validateOnly },
			body: request.relation ?? {},
			bodyType: 'sylphx.knowledge.v1.Relation',
			responseType: 'sylphx.knowledge.v1.Relation',
			mutation: true,
		})
	}

	/**
	 * Closes a fact (`close_fact`): it stopped holding in the world at
	 * `valid_end_time`. The fact stays readable for questions about the time
	 * before the close.
	 *
	 * `POST /v1/{name=orgs/*\/projects/*\/envs/*\/spaces/*\/relations/*}:close` · permission `knowledge:write` · effect `write`
	 *
	 * Errors: `UNAUTHENTICATED`, `PERMISSION_DENIED`, `RESOURCE_NOT_FOUND`, `INVALID_FIELD`, `INVALID_STATE`, `ETAG_MISMATCH`, `IDEMPOTENCY_KEY_REUSED`, `IDEMPOTENCY_IN_PROGRESS`.
	 *
	 * Short name of `sx.knowledge.relations.close`.
	 */
	async closeFact(request: CloseRelationRequest): Promise<Relation> {
		return this.client.call<Relation>({
			method: 'POST',
			path: `/v1/${runtime.pathParam(request.name, 'orgs/*/projects/*/envs/*/spaces/*/relations/*', 'name')}:close`,
			body: runtime.omit(request, ['name']),
			bodyType: 'sylphx.knowledge.v1.CloseRelationRequest',
			responseType: 'sylphx.knowledge.v1.Relation',
			mutation: true,
		})
	}
}

/** `spaces` of Sylphx Knowledge: Resource type `knowledge.sylphx.com/Space`. */
export class SpacesCollection {
	private readonly client: runtime.Client

	constructor(client: runtime.Client) {
		this.client = client
	}

	/**
	 * Gets a space.
	 *
	 * `GET /v1/{name=orgs/*\/projects/*\/envs/*\/spaces/*}` · permission `knowledge:read` · effect `read`
	 *
	 * Errors: `UNAUTHENTICATED`, `PERMISSION_DENIED`, `RESOURCE_NOT_FOUND`.
	 */
	async get(request: GetSpaceRequest): Promise<Space> {
		return this.client.call<Space>({
			method: 'GET',
			path: `/v1/${runtime.pathParam(request.name, 'orgs/*/projects/*/envs/*/spaces/*', 'name')}`,
			responseType: 'sylphx.knowledge.v1.Space',
			mutation: false,
		})
	}

	/**
	 * Lists spaces.
	 *
	 * `GET /v1/{parent=orgs/*\/projects/*\/envs/*}/spaces` · permission `knowledge:read` · effect `read`
	 *
	 * Errors: `UNAUTHENTICATED`, `PERMISSION_DENIED`, `INVALID_FIELD`, `PAGE_TOKEN_MISMATCH`.
	 */
	async list(request: ListSpacesRequest): Promise<ListSpacesResponse> {
		return this.client.call<ListSpacesResponse>({
			method: 'GET',
			path: `/v1/${runtime.pathParam(request.parent, 'orgs/*/projects/*/envs/*', 'parent')}/spaces`,
			query: { page_size: request.pageSize, page_token: request.pageToken, filter: request.filter, order_by: request.orderBy },
			responseType: 'sylphx.knowledge.v1.ListSpacesResponse',
			mutation: false,
		})
	}

	/** Every item of every page of `list`. */
	async *listAll(request: ListSpacesRequest): AsyncGenerator<Space> {
		let next: ListSpacesRequest = request
		for (;;) {
			const page = await this.list(next)
			yield* page.spaces ?? []
			if (page.nextPageToken === undefined || page.nextPageToken === '') return
			next = { ...request, pageToken: page.nextPageToken }
		}
	}

	/**
	 * Creates a space.
	 *
	 * `POST /v1/{parent=orgs/*\/projects/*\/envs/*}/spaces` · permission `knowledge:write` · effect `write`
	 *
	 * Errors: `UNAUTHENTICATED`, `PERMISSION_DENIED`, `UNKNOWN_FIELD`, `INVALID_FIELD`, `RESOURCE_ALREADY_EXISTS`, `IDEMPOTENCY_KEY_REUSED`, `IDEMPOTENCY_IN_PROGRESS`, `PLAN_LIMIT_REACHED`.
	 */
	async create(request: CreateSpaceRequest): Promise<Space> {
		return this.client.call<Space>({
			method: 'POST',
			path: `/v1/${runtime.pathParam(request.parent, 'orgs/*/projects/*/envs/*', 'parent')}/spaces`,
			query: { space_id: request.spaceId, validate_only: request.validateOnly },
			body: request.space ?? {},
			bodyType: 'sylphx.knowledge.v1.Space',
			responseType: 'sylphx.knowledge.v1.Space',
			mutation: true,
		})
	}

	/**
	 * Updates a space.
	 *
	 * `PATCH /v1/{space.name=orgs/*\/projects/*\/envs/*\/spaces/*}` · permission `knowledge:write` · effect `write`
	 *
	 * Errors: `UNAUTHENTICATED`, `PERMISSION_DENIED`, `RESOURCE_NOT_FOUND`, `UNKNOWN_FIELD`, `INVALID_FIELD`, `ETAG_MISMATCH`, `IDEMPOTENCY_KEY_REUSED`, `IDEMPOTENCY_IN_PROGRESS`.
	 */
	async update(request: UpdateSpaceRequest): Promise<Space> {
		return this.client.call<Space>({
			method: 'PATCH',
			path: `/v1/${runtime.pathParam(request.space?.name, 'orgs/*/projects/*/envs/*/spaces/*', 'space.name')}`,
			query: { update_mask: request.updateMask, allow_missing: request.allowMissing, validate_only: request.validateOnly },
			body: request.space ?? {},
			bodyType: 'sylphx.knowledge.v1.Space',
			responseType: 'sylphx.knowledge.v1.Space',
			mutation: true,
		})
	}

	/**
	 * Deletes a space. A space that still holds records is refused with
	 * `INVALID_STATE` unless `force` is set, which deletes its episodes and
	 * facts too.
	 *
	 * `DELETE /v1/{name=orgs/*\/projects/*\/envs/*\/spaces/*}` · permission `knowledge:write` · effect `destructive`
	 *
	 * Errors: `UNAUTHENTICATED`, `PERMISSION_DENIED`, `RESOURCE_NOT_FOUND`, `INVALID_STATE`, `ETAG_MISMATCH`, `IDEMPOTENCY_KEY_REUSED`, `IDEMPOTENCY_IN_PROGRESS`.
	 */
	async delete(request: DeleteSpaceRequest): Promise<Record<string, never>> {
		return this.client.call<Record<string, never>>({
			method: 'DELETE',
			path: `/v1/${runtime.pathParam(request.name, 'orgs/*/projects/*/envs/*/spaces/*', 'name')}`,
			query: { etag: request.etag, allow_missing: request.allowMissing, validate_only: request.validateOnly, force: request.force },
			mutation: true,
		})
	}
}

